mapper.select:
        select
        messageInfo.*,
        student.nick_name as stu_name,
        student.avatar as stu_img,
        teachers.name as tea_name,
        teachers.head_img as tea_img
        from message_info messageInfo
        left join users student on messageInfo.send_user_id = student.id
		left join teacher teachers on messageInfo.accept_user_id = teachers.id

            and messageInfo.id = #{id}
            and messageInfo.info = #{info}
            and messageInfo.message_id = #{messageId}
            and messageInfo.position = #{position}
            and messageInfo.send_user_id = #{sendUserId}
            and messageInfo.accept_user_id = #{acceptUserId}
            and messageInfo.create_time = #{createTime}
            and student.nick_name like concat('%',#{stuName},'%')
            and teachers.name like concat('%',#{teaName},'%')

        order by id asc

            limit #{current},#{pageSize}

        select count(*) from message_info messageInfo
        left join users student on messageInfo.send_user_id = student.id
		left join teacher teachers on messageInfo.accept_user_id = teachers.id

            and messageInfo.id = #{id}
            and messageInfo.info = #{info}
            and messageInfo.message_id = #{messageId}
            and messageInfo.position = #{position}
            and messageInfo.send_user_id = #{sendUserId}
            and messageInfo.accept_user_id = #{acceptUserId}
            and messageInfo.create_time = #{createTime}
            and student.nick_name like concat('%',#{stuName},'%')
            and teachers.name like concat('%',#{teaName},'%')
